<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?><header class="sd-site-header <?php echo sd_get_option( 'sd_sticky_header' ) ? 'is-sticky' : ''; ?>"><div class="sd-container sd-header-inner"><?php sd_render_site_branding(); ?><nav class="sd-main-nav" aria-label="<?php esc_attr_e( 'Primary menu', 'social-discovery' ); ?>"><?php sd_menu( 'primary' ); ?></nav><div class="sd-header-actions"><?php if ( sd_get_option( 'sd_header_search' ) ) : ?><a class="sd-icon-button" href="<?php echo esc_url( home_url( '/?s=' ) ); ?>" aria-label="<?php esc_attr_e( 'Search', 'social-discovery' ); ?>">⌕</a><?php endif; ?><button class="sd-icon-button sd-mode-toggle" type="button" data-sd-mode-toggle aria-pressed="false" aria-label="<?php esc_attr_e( 'Toggle color mode', 'social-discovery' ); ?>">◐</button><?php if ( is_user_logged_in() ) : ?><a class="sd-icon-button" href="<?php echo esc_url( sd_get_page_url( 'notifications' ) ); ?>" aria-label="<?php esc_attr_e( 'Notifications', 'social-discovery' ); ?>">♡</a><?php elseif ( sd_get_option( 'sd_header_auth' ) ) : ?><a class="sd-button sd-button-outline" href="<?php echo esc_url( wp_login_url() ); ?>"><?php esc_html_e( 'Log in', 'social-discovery' ); ?></a><a class="sd-button sd-button-primary" href="<?php echo esc_url( wp_registration_url() ); ?>"><?php esc_html_e( 'Join free', 'social-discovery' ); ?></a><?php endif; ?><?php if ( sd_get_option( 'sd_header_cta_enabled' ) && sd_get_option( 'sd_header_cta_url' ) ) : ?><a class="sd-button sd-button-primary" href="<?php echo esc_url( sd_get_option( 'sd_header_cta_url' ) ); ?>"><?php echo esc_html( sd_get_option( 'sd_header_cta_text' ) ); ?></a><?php endif; ?><button class="sd-menu-toggle" type="button" aria-expanded="false" aria-controls="sd-mobile-drawer" aria-label="<?php esc_attr_e( 'Open menu', 'social-discovery' ); ?>">☰</button></div></div><?php get_template_part( 'template-parts/header/mobile-menu' ); ?></header>
